/* ---- Register conventions ------------------------------------------------
 * x0-x7  : ARG1-ARG8 / caller-saved
 * x8     : indirect result register (avoid)
 * x9-x15 : TMP1-TMP7 / caller-saved temporaries
 * x16    : FUNCTION / IP0 (linker scratch, used for callp)
 * x17    : spare / IP1
 * x18    : platform register (reserved, do not touch)
 * x19    : TC  (callee-saved — MVMThreadContext*)
 * x20    : CU  (callee-saved — MVMCompUnit*)
 * x21    : WORK (callee-saved — MVMRegister* work array)
 * x29    : FP  (frame pointer)
 * x30    : LR  (link register)
 * v0     : RVF / FP argument 0
 * v1-v7  : FP arguments
 * v8-v15 : callee-saved FP
 * v16-v31: caller-saved FP temporaries
 * ----------------------------------------------------------------------- */
//|.define ARG1,     x0
//|.define ARG2,     x1
//|.define ARG3,     x2
//|.define ARG4,     x3
//|.define ARG5,     x4
//|.define ARG6,     x5
//|.define ARG1F,    v0
//|.define ARG2F,    v1
//|.define TMP1,     x9
//|.define TMP2,     x10
//|.define TMP3,     x11
//|.define TMP4,     x12
//|.define TMP5,     x13
//|.define TMP6,     x14
//|.define TMP7,     x15
//|.define FUNCTION, x16
//|.define RV,       x0
//|.define RVF,      v0

/* Call a C function whose address is known at JIT compile time.
 * Stores the pointer in the data section and loads it PC-relatively. */
//|.macro callp, funcptr
//|.data
//|5:
//|.quad (uintptr_t)(funcptr)
//|.code
//| ldr FUNCTION, <5
//| adr x17, >9
//| str x17, [sp, #40]
//| blr FUNCTION
//| ldr x17, [sp, #40]
//| br x17
//|9:
//|.endmacro

/* Call a C function whose address is in FUNCTION (x16), maintaining the
 * jit_return_address slot at [sp,#40] exactly like callp: the callee (or
 * anything it triggers — dispatch recording, GC, deopt, frame walks) can read
 * the current JIT position from *tc->jit_return_address, and a deopt may
 * REWRITE the slot to redirect us; hence the reload-and-branch on return.
 * A bare `blr FUNCTION` loses both properties (BLR only sets LR on AArch64,
 * unlike x64 CALL which pushes the return address where the walker finds it). */
//|.macro callf
//| adr x17, >9
//| str x17, [sp, #40]
//| blr FUNCTION
//| ldr x17, [sp, #40]
//| br x17
//|9:
//|.endmacro

/* GC safe-point: if gc_status != 0, call into the GC. */
